import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>


namespace cute_matmul_detail {
using namespace cute;

constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 8;
constexpr int THREADS = 256;
constexpr int THREAD_ROWS = 16;
constexpr int THREAD_COLS = 4;

__global__ __launch_bounds__(THREADS)
void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    __shared__ float smem_a[BM * BK];
    __shared__ float smem_b[BK * BN];

    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K, N),
        make_stride(N, Int<1>{}));

    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(M, N),
        make_stride(N, Int<1>{}));

    auto sA = make_tensor(
        make_smem_ptr(smem_a),
        make_shape(Int<BM>{}, Int<BK>{}),
        make_stride(Int<BK>{}, Int<1>{}));

    auto sB = make_tensor(
        make_smem_ptr(smem_b),
        make_shape(Int<BK>{}, Int<BN>{}),
        make_stride(Int<BN>{}, Int<1>{}));

    const int tid = threadIdx.x;
    const int block_row = blockIdx.y * BM;
    const int block_col = blockIdx.x * BN;

    const int thread_group = tid / 32;
    const int lane = tid % 32;

    const int row_base = thread_group * THREAD_ROWS;
    const int col_base = lane * THREAD_COLS;

    float accum[THREAD_ROWS][THREAD_COLS];

    #pragma unroll
    for (int i = 0; i < THREAD_ROWS; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_COLS; ++j) {
            accum[i][j] = 0.0f;
        }
    }

    for (int k_tile = 0; k_tile < K; k_tile += BK) {
        for (int linear = tid; linear < BM * BK; linear += THREADS) {
            const int local_row = linear / BK;
            const int local_k = linear % BK;
            const int global_row = block_row + local_row;
            const int global_k = k_tile + local_k;

            sA(local_row, local_k) =
                (global_row < M && global_k < K)
                    ? gA(global_row, global_k)
                    : 0.0f;
        }

        for (int linear = tid; linear < BK * BN; linear += THREADS) {
            const int local_k = linear / BN;
            const int local_col = linear % BN;
            const int global_k = k_tile + local_k;
            const int global_col = block_col + local_col;

            sB(local_k, local_col) =
                (global_k < K && global_col < N)
                    ? gB(global_k, global_col)
                    : 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_frag[THREAD_ROWS];
            float b_frag[THREAD_COLS];

            #pragma unroll
            for (int i = 0; i < THREAD_ROWS; ++i) {
                a_frag[i] = sA(row_base + i, kk);
            }

            #pragma unroll
            for (int j = 0; j < THREAD_COLS; ++j) {
                b_frag[j] = sB(kk, col_base + j);
            }

            #pragma unroll
            for (int i = 0; i < THREAD_ROWS; ++i) {
                #pragma unroll
                for (int j = 0; j < THREAD_COLS; ++j) {
                    accum[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }

        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < THREAD_ROWS; ++i) {
        const int global_row = block_row + row_base + i;
        if (global_row < M) {
            #pragma unroll
            for (int j = 0; j < THREAD_COLS; ++j) {
                const int global_col = block_col + col_base + j;
                if (global_col < N) {
                    gC(global_row, global_col) = accum[i][j];
                }
            }
        }
    }
}

} // namespace cute_matmul_detail

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat &&
                B.scalar_type() == at::kFloat,
                "A and B must be float32 tensors");
    TORCH_CHECK(A.size(1) == B.size(0),
                "A.size(1) must equal B.size(0)");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    const int M = static_cast<int>(A_contig.size(0));
    const int K = static_cast<int>(A_contig.size(1));
    const int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::BN - 1) / cute_matmul_detail::BN,
        (M + cute_matmul_detail::BM - 1) / cute_matmul_detail::BM);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matmul_detail::cute_matmul_kernel<<<grid, block, 0, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE matrix multiplication kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

